Here's how to handle each scenario with modern MSTest (3.9+/3.10+) attributes:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class MyTests
{
    private string? _tempFile;

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        // Skipped automatically on Linux/macOS
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_ProducesValidOutput()
    {
        // Only runs locally, skipped in CI
        var result = GpuRenderer.RenderFrame();
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    public async Task GetWeather_ReturnsForecast()
    {
        var forecast = await WeatherClient.GetForecastAsync("Seattle");
        Assert.IsNotNull(forecast);
    }

    // 4. Cleanup temp files even on failure
    [TestMethod]
    public void ExportData_WritesToFile()
    {
        _tempFile = Path.GetTempFileName();
        DataExporter.Export(_tempFile);
        Assert.IsTrue(File.Exists(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        // Runs after EVERY test, even on failure
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Summary:**

| Scenario | Solution |
|----------|----------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` — skips on other OS |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` — skips when CI env detected |
| Flaky API | `[Retry(3)]` — retries up to 3 times before failing |
| Temp file cleanup | `[TestCleanup]` method — always runs, even on test failure |

**Requirements:** `[OSCondition]` needs MSTest 3.10+, `[CICondition]` needs 3.10+, `[Retry]` needs 3.9+. All are available with the current `MSTest` metapackage or `MSTest.Sdk`.
